/** Original editorial photography. The registry packs these images into the installed template. */
export const GARDEN_IMAGES = {
  ferry: "data:image/webp;base64,",
  gloves: "data:image/webp;base64,",
  type: "data:image/webp;base64,",
  estimate: "data:image/webp;base64,",
  rooms: "data:image/webp;base64,",
  kiln: "data:image/webp;base64,",
  fieldnotes: "data:image/webp;base64,",
}

import { PERSON, POSTS } from "../portfolio/data"

function xml(value: string) {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
}

/** Resolve item URLs against the actual mount point, in both the demo and the installed site. */
export function portfolioFeed(request: Request) {
  const home = new URL("./", request.url)
  const items = POSTS.map((post) => {
    const href = xml(new URL("writing/" + encodeURIComponent(post.slug), home).href)
    const published = new Date(post.date + "T00:00:00Z").toUTCString()
    return `<item><title>${xml(post.title)}</title><link>${href}</link><guid>${href}</guid><pubDate>${published}</pubDate><description>${xml(post.summary)}</description></item>`
  })
  const rss = `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>${xml(PERSON.name)}</title><link>${xml(home.href)}</link><description>Essays and notes from ${xml(PERSON.city)}.</description>${items.join("")}</channel></rss>`
  return new Response(rss, { headers: { "Content-Type": "application/rss+xml; charset=utf-8" } })
}

import Image from "next/image"
import Link from "next/link"

import { cn } from "@/lib/utils"

import { POSTS } from "../portfolio/data"

import { EDITIONS, type GardenBlock } from "./garden-data"
import { GardenHeader, GardenLeaf, GardenNewsletter } from "./garden-frame"
import { GARDEN_IMAGES } from "./assets"
import { GardenContents } from "./garden-contents"
import { GARDEN_NOTES } from "./garden-notes-data"
import { to } from "../portfolio/site"
import { Prose } from "../portfolio/writing"

const serif = "font-[family-name:var(--dc-font-heading)]"
const dateFormat = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" })
const shortDateFormat = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" })

function dateLabel(iso: string, formatter = dateFormat) {
  return formatter.format(new Date(`${iso}T00:00:00Z`))
}

function GardenText({ text }: { text: string }) {
  return text.split(/(`[^`]+`)/).map((part, index) =>
    part.startsWith("`") && part.endsWith("`") && part.length > 1 ? (
      <code key={index} className="rounded bg-muted px-1.5 py-0.5 font-mono text-[.83em]">
        {part.slice(1, -1)}
      </code>
    ) : part,
  )
}

function ArticleBlock({
  block,
  headingId,
  noteNumber,
  opening,
}: {
  block: GardenBlock
  headingId?: string
  noteNumber?: number
  opening: boolean
}) {
  switch (block.type) {
    case "p": {
      const aside = "sidenote" in block && noteNumber ? { number: noteNumber, text: block.sidenote } : null
      return (
        <div className={cn(aside && "lg:grid lg:grid-cols-[minmax(0,1fr)_0] lg:items-start", !opening && "mt-1.5")}>
          <p className={cn(
            opening && "first-letter:float-left first-letter:mt-0.5 first-letter:mr-4 first-letter:font-[family-name:var(--dc-font-heading)] first-letter:text-[4.4em] first-letter:leading-[.78] first-letter:font-semibold first-letter:italic sm:first-letter:mr-6 lg:first-letter:mb-[.2em]",
          )}>
            <GardenText text={block.text} />
            {aside ? (
              <sup>
                <a
                  id={`note-ref-${aside.number}`}
                  href={`#sidenote-${aside.number}`}
                  aria-label={`Read note ${aside.number}`}
                  className="scroll-mt-8 px-0.5 font-semibold underline-offset-2 hover:underline focus-visible:outline-2"
                >
                  {aside.number}
                </a>
              </sup>
            ) : null}
          </p>
          {aside ? (
            <aside
              id={`sidenote-${aside.number}`}
              tabIndex={-1}
              aria-label={`Note ${aside.number}`}
              className={cn(
                serif,
                "relative mt-3 scroll-mt-8 pl-4 text-sm leading-snug text-muted-foreground italic lg:mt-1 lg:ml-[var(--garden-article-gap)] lg:w-[clamp(7rem,13vw,11rem)] lg:text-[clamp(1rem,1.4vw,1.25rem)]",
              )}
            >
              <a
                href={`#note-ref-${aside.number}`}
                aria-label={`Return to note ${aside.number} in the essay`}
                className="absolute top-0 left-0 text-[.7em] underline-offset-2 hover:underline focus-visible:outline-2"
              >
                {aside.number}
              </a>
              <GardenText text={aside.text} />
            </aside>
          ) : null}
        </div>
      )
    }
    case "h2":
      return (
        <h2
          id={headingId}
          tabIndex={-1}
          className={cn(serif, "mt-[clamp(1.5rem,2.35vw,2.125rem)] scroll-mt-8 text-[clamp(1.625rem,2.9vw,2.625rem)] leading-[1.06] font-semibold tracking-tight italic")}
        >
          {block.text}
        </h2>
      )
    case "figure":
      return (
        <figure className="mt-[clamp(1.875rem,5vw,4.75rem)]">
          <div className="relative aspect-[1.88] bg-[color:var(--dc-surface)]">
            <Image src={GARDEN_IMAGES[block.image]} alt={block.alt} fill unoptimized sizes="(min-width: 1024px) 58vw, 94vw" className="object-cover" />
          </div>
          <figcaption className={cn(serif, "mt-2 text-[clamp(.95rem,1.55vw,1.375rem)] leading-snug italic")}>
            {block.caption}
          </figcaption>
        </figure>
      )
    case "quote":
      return (
        <blockquote className={cn(serif, "mt-[clamp(1.5rem,2.5vw,2.375rem)] border-l-4 border-[color:var(--dc-highlight)] py-1 pl-5 text-[clamp(1.625rem,3.05vw,2.75rem)] leading-[1.12] font-medium tracking-tight italic sm:pl-7")}>
          <GardenText text={block.text} />
        </blockquote>
      )
    case "list":
      return (
        <ul className="mt-4 grid list-disc gap-2 pl-6 marker:text-muted-foreground">
          {block.items.map((item, index) => <li key={index}><GardenText text={item} /></li>)}
        </ul>
      )
    case "note":
      return (
        <aside className="mt-5 border-l-2 border-[color:var(--dc-highlight)] pl-4 text-[.9em] text-muted-foreground">
          <span className="font-medium text-foreground">Note. </span><GardenText text={block.text} />
        </aside>
      )
    case "code":
      return <Prose blocks={[block]} className="mt-5" />
  }
}

export function GardenArticle({ base, slug }: { base: string; slug: string }) {
  const post = POSTS.find((item) => item.slug === slug)
  if (!post) return null

  const { body, figure, summary, updated } = EDITIONS[post.slug] ?? {}
  const blocks = body ?? (figure ? [...post.body.slice(0, 1), figure, ...post.body.slice(1)] : post.body)
  const openingParagraph = blocks.findIndex((block) => block.type === "p")
  const linkedNotes = GARDEN_NOTES.filter((note) => note.links.includes(slug))
  const headings: { id: string; label: string }[] = []
  const headingIds = new Set<string>()
  let noteCount = 0
  const articleBlocks = blocks.map((block, index) => {
    let headingId: string | undefined
    if (block.type === "h2") {
      const headingBase = block.text.toLowerCase().replace(/[^\p{Letter}\p{Number}]+/gu, "-").replace(/^-|-$/g, "") || "section"
      headingId = headingBase
      for (let suffix = 2; headingIds.has(headingId); suffix += 1) {
        headingId = `${headingBase}-${suffix}`
      }
      headingIds.add(headingId)
      headings.push({ id: headingId, label: block.text })
    }
    const noteNumber = "sidenote" in block ? ++noteCount : undefined
    return <ArticleBlock key={index} block={block} headingId={headingId} noteNumber={noteNumber} opening={index === openingParagraph} />
  })

  return (
    <>
      <GardenHeader base={base} />
      <main id="main">
        <article className="mx-auto grid w-full max-w-[1440px] px-5 pt-[clamp(1.625rem,2.65vw,2.5rem)] pb-[clamp(2rem,3.2vw,3rem)] sm:px-[min(3vw,2.75rem)] lg:grid-cols-[minmax(0,1fr)_minmax(0,61%)_minmax(0,1fr)] lg:gap-x-[var(--garden-article-gap)] lg:[--garden-article-gap:clamp(1.75rem,5.2vw,4.75rem)]">
          <header className="mb-[clamp(1.625rem,2.8vw,2.625rem)] min-w-0 lg:col-start-2">
            <p className="flex flex-wrap items-center gap-x-2.5 text-[clamp(1rem,1.75vw,1.5rem)] leading-snug">
              <span>Essay</span>
              <span aria-hidden="true">·</span>
              <GardenLeaf stage="Evergreen" />
            </p>
            <h1 className={cn(serif, "mt-2 max-w-[9.35em] text-[clamp(2.625rem,5.2vw,4.625rem)] leading-[.99] font-semibold tracking-[-.035em] italic")}>
              {post.title}
            </h1>
            <p className={cn(serif, "mt-3 text-[clamp(1.25rem,1.77vw,1.625rem)] leading-snug italic lg:-mr-10")}>
              {summary ?? post.summary}
            </p>
            <p className="mt-2.5 flex flex-wrap items-baseline gap-x-1.5 gap-y-1 text-[clamp(.875rem,1.48vw,1.25rem)] leading-snug">
              <span>{post.minutes} min read</span>
              <span aria-hidden="true">·</span>
              <time dateTime={post.date}>{dateLabel(post.date)}</time>
              {updated ? (
                <>
                  <span aria-hidden="true">·</span>
                  <span>Updated <time dateTime={updated}>{dateLabel(updated, updated.slice(0, 4) === post.date.slice(0, 4) ? shortDateFormat : dateFormat)}</time></span>
                </>
              ) : null}
            </p>
          </header>
          <GardenContents key={post.slug} headings={headings} />
          <div className="min-w-0 text-[clamp(1.125rem,1.86vw,1.625rem)] leading-[1.3] tracking-[-.01em] lg:col-start-2 lg:row-start-2">
            {articleBlocks}
          </div>
          {linkedNotes.length ? (
            <section aria-labelledby="linked-notes-title" className="mt-[clamp(1.625rem,2.4vw,2.25rem)] border-t border-border pt-3 lg:col-start-2 lg:-mx-[clamp(1.25rem,3.2vw,3rem)]">
              <h2 id="linked-notes-title" className={cn(serif, "text-[clamp(1.375rem,2.05vw,1.875rem)] leading-tight font-semibold italic")}>Linked from</h2>
              <ul className="mt-2.5 grid gap-3 sm:grid-cols-2 sm:gap-5">
                {linkedNotes.map((note) => (
                  <li key={note.slug}>
                    <Link
                      href={`${to(base)}#note-${note.slug}`}
                      className="group block h-full rounded-xl border border-border px-4 py-3 transition-colors hover:bg-[color:var(--dc-surface)] focus-visible:outline-2 focus-visible:outline-offset-3 sm:px-5"
                    >
                      <div className="text-[clamp(.875rem,1.4vw,1.25rem)]"><GardenLeaf stage={note.stage} /></div>
                      <p className={cn(serif, "mt-1 text-[clamp(1.35rem,2.05vw,1.875rem)] leading-tight font-semibold tracking-tight underline-offset-4 group-hover:underline")}>
                        {note.title}
                      </p>
                    </Link>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}
        </article>
        <GardenNewsletter />
      </main>
    </>
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

import { cn } from "@/lib/utils"

type Heading = { id: string; label: string }

export function GardenContents({ headings }: { headings: Heading[] }) {
  const [activeId, setActiveId] = useState(headings[0]?.id)
  const jump = useRef<{ id: string; reached: boolean } | null>(null)

  useEffect(() => {
    const targets = headings.flatMap(({ id }) => {
      const element = document.getElementById(id)
      return element ? [element] : []
    })
    if (targets.length === 0) return

    let frame: number | undefined
    function update() {
      frame = undefined
      const scrollY = window.scrollY
      const scrollEnd = document.documentElement.scrollHeight - window.innerHeight
      const selected = jump.current
      if (selected) {
        const anchor = targets.find((target) => target.id === selected.id)
        if (anchor) {
          const margin = Number.parseFloat(getComputedStyle(anchor).scrollMarginTop) || 0
          const destination = Math.min(scrollEnd, Math.max(0, scrollY + anchor.getBoundingClientRect().top - margin))
          // Multiple nearby headings can land at the same scroll position at the end of a page.
          if (Math.abs(scrollY - destination) < 2) {
            selected.reached = true
            setActiveId(selected.id)
            return
          }
        }
        if (selected.reached) jump.current = null
      }

      const readingLine = Math.min(180, window.innerHeight * 0.28)
      const atEnd = scrollY > 0 && scrollY >= scrollEnd - 2
      const current = atEnd ? targets.at(-1) : targets.findLast((target) => target.getBoundingClientRect().top <= readingLine)
      setActiveId((current ?? targets[0]).id)
    }

    function scheduleUpdate() {
      frame ??= window.requestAnimationFrame(update)
    }

    function onHashChange() {
      const target = targets.find(({ id }) => window.location.hash === `#${encodeURIComponent(id)}`)
      jump.current = target ? { id: target.id, reached: false } : null
      scheduleUpdate()
    }

    onHashChange()
    window.addEventListener("scroll", scheduleUpdate, { passive: true })
    window.addEventListener("resize", scheduleUpdate)
    window.addEventListener("hashchange", onHashChange)
    return () => {
      if (frame !== undefined) window.cancelAnimationFrame(frame)
      window.removeEventListener("scroll", scheduleUpdate)
      window.removeEventListener("resize", scheduleUpdate)
      window.removeEventListener("hashchange", onHashChange)
    }
  }, [headings])

  if (headings.length === 0) return null

  return (
    <nav
      aria-label="Contents"
      className="mb-6 min-w-0 border-y border-border py-3 text-sm lg:sticky lg:top-8 lg:col-start-1 lg:row-start-2 lg:mb-0 lg:self-start lg:border-0 lg:py-1 lg:text-[clamp(.95rem,1.55vw,1.25rem)]"
    >
      <p className="font-[family-name:var(--dc-font-heading)] text-base font-semibold italic lg:text-[1.08em]">Contents</p>
      <ol className="mt-2 flex flex-wrap gap-x-4 gap-y-1.5 lg:mt-4 lg:grid lg:gap-2.5">
        {headings.map(({ id, label }) => (
          <li key={id}>
            <a
              href={`#${id}`}
              aria-current={id === activeId ? "location" : undefined}
              onClick={() => {
                jump.current = { id, reached: false }
                setActiveId(id)
              }}
              className={cn(
                "leading-snug underline-offset-4 hover:text-foreground hover:underline focus-visible:rounded-xs focus-visible:outline-2 focus-visible:outline-offset-3",
                id === activeId ? "font-semibold text-foreground" : "text-muted-foreground",
              )}
            >
              {label}
            </a>
          </li>
        ))}
      </ol>
    </nav>
  )
}

// What only the Garden layout shows, beside the content it shares with the Portfolio template
// (components/portfolio/data.ts): an editorial version of a post (a standfirst, numbered margin notes,
// photographs) and a short caption for each project on the home page. Keyed by slug; a post or
// project with no entry here uses its shared text.
import type { Block } from "../portfolio/data"

import type { GARDEN_IMAGES } from "./assets"

export type GardenFigure = { type: "figure"; image: keyof typeof GARDEN_IMAGES; alt: string; caption: string }

/** A paragraph can carry a margin note; a figure is one of the sample photographs. */
export type GardenBlock = Block | { type: "p"; text: string; sidenote: string } | GardenFigure

export type Edition = { summary?: string; updated?: string; body?: GardenBlock[]; figure?: GardenFigure }

/** The issue line under your name on the home page. */
export const ISSUE = "Issue 14 · November 2026"

export const EDITIONS: Record<string, Edition> = {
  "design-for-gloves": {
    summary: "On a wet morning, the easiest button to find is the one you can feel sure of.",
    updated: "2026-11-02",
    body: [
      {
        type: "p",
        text: "The first time I tried to save a note on the quay, I took my glove off. Rain ran down the glass while I aimed for a small tick in the corner. I went home with a wet hand and a better idea of what the button needed to do.",
        sidenote: "The first trial was on the morning crossing.",
      },
      { type: "h2", text: "Cold hands" },
      { type: "p", text: "The wool at the tip of my thumb covered both the tick and the cross beside it. I could see the two controls until I reached for one." },
      { type: "h2", text: "A bigger target" },
      { type: "p", text: "I moved Save into a wide button at the foot of the screen. The next morning I could reach it with my thumb while my other hand held the notebook." },
      { type: "figure", image: "gloves", alt: "A gloved thumb reaches a wide green Save note button on a rain-covered phone by the water.", caption: "Testing Fieldnotes on the quay." },
      { type: "h2", text: "Reading the screen" },
      {
        type: "p",
        text: "Pale grey text vanished in the reflection of the sky. A darker label stayed readable when I tilted the screen toward the water.",
        sidenote: "Wet glass caught the brightest part of the sky.",
      },
      { type: "quote", text: "A button earns its place on a cold morning." },
      { type: "h2", text: "Back at the quay" },
      { type: "p", text: "The useful test was simple. Could I save what I had seen before the ferry pulled away?" },
    ],
  },
  "a-map-that-breathes": {
    summary: "A live map of eleven ferry lines, where small changes add up to a calmer, more useful picture of the city.",
    figure: { type: "figure", image: "ferry", alt: "A ferry route display stands beside the water.", caption: "The Tidewater display at the ferry pier." },
  },
  "variable-fonts-as-instruments": {
    figure: { type: "figure", image: "type", alt: "A type specimen shows letterforms at different weights.", caption: "A specimen from Lumen Type." },
  },
  "pricing-small-projects": {
    figure: { type: "figure", image: "estimate", alt: "A paper project estimate with handwritten notes.", caption: "Working through the scope of a small project." },
  },
}

/** Short captions under the work on the home page. */
export const CAPTIONS: Record<string, string> = {
  "fieldnotes": "An offline-first notebook for botanists.",
  "kiln": "Booking for a pottery studio.",
  "small-rooms": "Forty flats under 30 m².",
}

import Link from "next/link"

import { PERSON } from "../portfolio/data"
import { to } from "../portfolio/site"
import { ModeToggle, NewsletterForm } from "../portfolio/ui"

import { ISSUE } from "./garden-data"

export { GardenLeaf } from "./garden-leaf"

const wrap = "mx-auto w-full max-w-[1440px] px-5 sm:px-8 lg:px-10"
const navLink = "rounded-sm underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-current"

export function GardenHeader({ base, home = false }: { base: string; home?: boolean }) {
  const links = [
    ["Essays", home ? "#essays" : to(base, "writing")],
    ["Notes", home ? "#garden" : to(base) + "#garden"],
    ["Work", home ? "#work" : to(base, "work")],
    ["About", to(base, "about")],
    ...(home ? [["Now", to(base, "now")], ["Subscribe", "#subscribe"]] : []),
  ]
  return (
    <header className={wrap + " print:hidden"}>
      <a href="#main" className="sr-only z-50 rounded-sm bg-background p-2 focus:not-sr-only focus:fixed focus:top-2 focus:left-2">Skip to content</a>
      {home ? (
        <div className="relative py-4 text-center sm:pt-5 sm:pb-4">
          <h1 className="dc-h px-9 text-[clamp(2.4rem,6.8vw,6.2rem)] leading-none italic">{PERSON.name}</h1>
          <p className="mt-2 text-sm text-muted-foreground sm:text-base lg:text-xl">Essays, notes and work from {PERSON.city} · {ISSUE}</p>
          <ModeToggle className="absolute top-3 right-0" />
        </div>
      ) : null}
      <div className={home ? "border-y border-border" : "flex flex-wrap items-center justify-between gap-x-6 gap-y-2 border-b border-border py-2 md:py-3"}>
        {home ? null : <Link href={to(base)} className="dc-h text-[clamp(1.75rem,3.2vw,3.2rem)] leading-none italic">{PERSON.name}</Link>}
        <nav aria-label="Portfolio" className={home ? "flex flex-wrap items-center justify-center gap-x-[clamp(1rem,5.4vw,5.3rem)] gap-y-2 py-3 text-sm sm:text-base lg:text-lg" : "flex flex-wrap items-center gap-x-4 gap-y-1 text-sm sm:gap-x-7 sm:text-base"}>
          {links.map(([label, href]) => <Link key={label} href={href} className={navLink}>{label}</Link>)}
          {home ? null : <ModeToggle />}
        </nav>
      </div>
    </header>
  )
}

export function GardenNewsletter() {
  return (
    <section id="subscribe" aria-labelledby="garden-newsletter" className="dc-band scroll-mt-3 print:hidden">
      <div className={wrap + " grid items-center gap-x-7 gap-y-3 py-6 lg:grid-cols-[auto_1fr_minmax(300px,0.95fr)]"}>
        <h2 id="garden-newsletter" className="dc-h text-[clamp(1.8rem,3.1vw,3rem)] leading-none italic">Get the next issue</h2>
        <p className="text-sm lg:border-l lg:border-[var(--dc-band-edge)] lg:pl-7">One letter a month. Essays first, notes after.</p>
        <NewsletterForm placeholder="Your email" confirmation="Thanks for trying the newsletter preview." className="w-full max-w-none [&_input]:min-w-0 [&_input]:bg-[var(--dc-surface)] [&_input]:text-[var(--dc-ink)] [&_input]:placeholder:text-[var(--dc-muted)]" />
      </div>
    </section>
  )
}

export function GardenFooter({ base }: { base: string }) {
  const columns = [
    [["Essays", to(base, "writing")], ["Notes", to(base) + "#garden"], ["Work", to(base, "work")]],
    [["About", to(base, "about")], ["Now", to(base, "now")], ["Uses", to(base, "uses")]],
    [["RSS", to(base, "feed.xml")], ["Email", "mailto:" + PERSON.email], ["Résumé", to(base, "resume")]],
  ]
  return (
    <footer className={wrap + " grid grid-cols-3 print:hidden gap-x-5 gap-y-4 py-6 text-sm sm:grid-cols-[1fr_repeat(3,minmax(4rem,0.18fr))]"}>
      <p className="col-span-3 text-muted-foreground sm:col-span-1"><span className="hidden [[data-pf-theme=matcha]_&]:inline">Set in Fraunces and Instrument Sans.<br /></span>Written and built in {PERSON.city}.</p>
      {columns.map((links) => <ul key={links[0][0]} className="space-y-1">{links.map(([label, href]) => (
        <li key={label}>{label === "RSS" || label === "Email"
          ? <a href={href} className="text-[var(--dc-accent)] underline underline-offset-2">{label}</a>
          : <Link href={href} className="text-[var(--dc-accent)] underline underline-offset-2">{label}</Link>}</li>
      ))}</ul>)}
    </footer>
  )
}

import Image from "next/image"
import Link from "next/link"

import { cn } from "@/lib/utils"

import { POSTS, PROJECTS, type Post } from "../portfolio/data"
import { GardenFooter, GardenHeader, GardenNewsletter } from "./garden-frame"
import { CAPTIONS, EDITIONS } from "./garden-data"
import { GARDEN_IMAGES } from "./assets"
import { GardenNotes } from "./garden-notes"
import { GARDEN_NOTES } from "./garden-notes-data"
import { to } from "../portfolio/site"

const FEATURED_SLUG = "a-map-that-breathes"

const SAMPLE_WORK = [
  {
    slug: "small-rooms",
    src: GARDEN_IMAGES.rooms,
    alt: "An open photo book with photographs and a floor plan of a small flat",
  },
  {
