              // The cover you point at wipes in from below; the ones above it have wiped out the top.
              style={{ clipPath: activeAt === i ? "inset(0 0 0 0)" : activeAt >= 0 && i < activeAt ? "inset(0 0 100% 0)" : "inset(100% 0 0 0)", zIndex: activeAt === i ? 2 : 1 }}
